INSERT INTO `questions` (`id`, `exam_id`, `subject_id`, `content`, `image_url`, `question_type`, `points`, `order_index`, `explanation`, `explanation_image_url`, `created_at`, `updated_at`) VALUES
(18, 9, 1, 'Đỉnh I của parabol (P): y = -x² + 4x - 3 có tọa độ là:', 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=900&auto=format&fit=crop&q=80', 'single_choice', 2.00, 1, 'Tọa độ đỉnh x = -b/(2a) = -4/(2*(-1)) = 2. Khi x = 2 thì y = -(2)^2 + 4*(2) - 3 = 1. Do đó I(2; 1).', 'https://images.unsplash.com/photo-1509228468518-180dd4864904?w=800&auto=format&fit=crop&q=80', '2026-10-09 10:38:35', '2026-10-09 10:38:35'),
(19, 9, 1, 'Trục đối xứng của parabol y = 2x² + 4x + 1 là đường thẳng:', NULL, 'single_choice', 2.00, 2, 'Trục đối xứng có phương trình x = -b/(2a) = -4/(2*2) = -1.', NULL, '2026-10-09 10:38:35', '2026-10-09 10:38:35'),
(20, 9, 1, 'Hàm số y = x² - 4x + 3 đồng biến trên khoảng nào sau đây?', NULL, 'single_choice', 2.00, 3, 'Hệ số a = 1 > 0, bề lõm quay lên trên, đỉnh x = 2. Hàm số đồng biến trên khoảng (2; + vô cùng).', NULL, '2026-10-09 10:38:35', '2026-10-09 10:38:35'),
(21, 9, 1, 'Tập xác định của hàm số y = √(x - 3) là:', NULL, 'single_choice', 2.00, 4, 'Điều kiện xác định: x - 3 >= 0 <=> x >= 3. Vậy D = [3; + vô cùng).', NULL, '2026-10-09 10:38:35', '2026-10-09 10:38:35'),
(22, 9, 1, 'Giá trị nhỏ nhất của hàm số y = x² - 2x + 5 đạt được khi x bằng:', NULL, 'single_choice', 2.00, 5, 'y = (x - 1)² + 4 >= 4 với mọi x. Giá trị nhỏ nhất là 4 khi x = 1.', NULL, '2026-10-09 10:38:35', '2026-10-09 10:38:35'),
(23, 10, 1, 'Giá trị nhỏ nhất của hàm số y = x² - 2x + 5 đạt được khi x bằng:', NULL, 'single_choice', 2.00, 1, 'y = (x - 1)² + 4 >= 4 với mọi x. Giá trị nhỏ nhất là 4 khi x = 1.', NULL, '2026-11-04 07:35:07', '2026-11-04 07:35:07'),
(24, 10, 1, 'Đỉnh I của parabol (P): y = -x² + 4x - 3 có tọa độ là:', 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=900&auto=format&fit=crop&q=80', 'single_choice', 2.00, 2, 'Tọa độ đỉnh x = -b/(2a) = -4/(2*(-1)) = 2. Khi x = 2 thì y = -(2)^2 + 4*(2) - 3 = 1. Do đó I(2; 1).', 'https://images.unsplash.com/photo-1509228468518-180dd4864904?w=800&auto=format&fit=crop&q=80', '2026-11-04 07:35:07', '2026-11-04 07:35:07'),
(25, 10, 1, 'Trục đối xứng của parabol y = 2x² + 4x + 1 là đường thẳng:', NULL, 'single_choice', 2.00, 3, 'Trục đối xứng có phương trình x = -b/(2a) = -4/(2*2) = -1.', NULL, '2026-11-04 07:35:07', '2026-11-04 07:35:07'),
(26, 10, 1, 'Hàm số y = x² - 4x + 3 đồng biến trên khoảng nào sau đây?', NULL, 'single_choice', 2.00, 4, 'Hệ số a = 1 > 0, bề lõm quay lên trên, đỉnh x = 2. Hàm số đồng biến trên khoảng (2; + vô cùng).', NULL, '2026-11-04 07:35:07', '2026-11-04 07:35:07'),
(27, 9, 52, 'Một ô tô xuất phát từ trạng thái nghỉ, chuyển động thẳng biến đổi đều với gia tốc a = 2 m/s² trong thời gian t = 5 s. Quãng đường ô tô đi được trong khoảng thời gian này là bao nhiêu?', NULL, 'single_choice', 2.00, 0, 'Quãng đường s = v₀·t + ½·a·t² (v₀ = 0 vì xuất phát từ nghỉ)\ns = ½·2·5² = 1·25 = 25 m.\n---', NULL, '2026-11-09 09:26:47', '2026-11-11 16:36:12'),
(28, 9, 52, 'Một vật chuyển động thẳng biến đổi đều với gia tốc a = 3 m/s² và vận tốc ban đầu v₀ = 4 m/s. Khi vật đã di chuyển được quãng đường s = 20 m, vận tốc của nó bằng bao nhiêu?', NULL, 'single_choice', 2.00, 0, 'Dùng công thức v² = v₀² + 2·a·s\nv² = 4² + 2·3·20 = 16 + 120 = 136 → v = √136 ≈ 11,66 m/s (làm tròn 11,7 m/s).\n---', NULL, '2026-11-09 09:26:47', '2026-11-11 16:38:38'),
(29, 9, 52, 'Một viên đá được ném thẳng lên trên với vận tốc ban đầu v₀ = 20 m/s. Lấy gia tốc trọng trường g = 10 m/s² (hướng xuống). Thời gian để viên đá đạt độ cao cực đại là bao nhiêu?', NULL, 'single_choice', 2.00, 0, 'Ở độ cao cực đại, vận tốc cuối cùng v = 0.\nv = v₀ – g·t → 0 = 20 – 10·t → t = 20/10 = 2 s.\n---\n*Các câu hỏi trên đã được định dạng theo chuẩn EduTest: nội dung rõ ràng, công thức viết bằng ký hiệu Unicode, 4 đáp án A‑D, chỉ ra đáp án đúng và kèm giải thích ngắn gọn.*', NULL, '2026-11-09 09:26:47', '2026-11-11 16:39:36'),
(30, 9, 67, 'Theo Hiến pháp Việt Nam 2013, quyền tự do ngôn luận được bảo hộ trong phạm vi nào?', NULL, 'single_choice', 2.00, 0, 'Hiến pháp quy định quyền tự do ngôn luận được bảo hộ, nhưng có thể bị hạn chế khi vi phạm luật an ninh quốc gia, trật tự công cộng, hoặc xâm phạm danh dự, nhân phẩm của người khác. Các trường hợp A, C, D không phù hợp với quy định hiến pháp.\n---', NULL, '2026-11-09 09:27:07', '2026-11-11 16:39:17'),
(31, 9, 67, 'Trong hệ thống pháp luật Việt Nam, “luật” được ban hành bởi cơ quan nào?', NULL, 'single_choice', 2.00, 0, 'Luật là văn bản pháp luật do Quốc hội ban hành (hoặc ủy ban thường vụ Quốc hội). Chủ tịch nước, Chính phủ và Tòa án nhân dân tối cao có thẩm quyền ban hành các loại văn bản khác (nghị quyết, quyết định, nghị định, án lệ).\n---', NULL, '2026-11-09 09:27:07', '2026-11-11 16:39:00'),
(32, 9, 67, 'Người dân có nghĩa vụ gì khi biết có hành vi vi phạm pháp luật?', NULL, 'single_choice', 2.00, 0, 'Theo quy định của pháp luật, khi biết có hành vi vi phạm, công dân có nghĩa vụ báo cáo cho cơ quan công an hoặc cơ quan quản lý nhà nước có thẩm quyền. Điều này giúp phát hiện, ngăn chặn và xử lý vi phạm kịp thời. Các đáp án A, C, D không đáp ứng yêu cầu pháp lý.\n---', NULL, '2026-11-09 09:27:07', '2026-11-11 16:38:25'),
(33, 9, 67, 'Khái niệm “trách nhiệm dân sự” trong pháp luật Việt Nam được hiểu là gì?', NULL, 'single_choice', 2.00, 0, 'Trách nhiệm dân sự là nghĩa vụ bồi thường thiệt hại (vật chất, tinh thần) cho người bị thiệt hại do hành vi vi phạm pháp luật dân sự (ví dụ: vi phạm hợp đồng, gây tai nạn). Các đáp án A, C, D đề cập đến các loại trách nhiệm khác.\n---', NULL, '2026-11-09 09:27:07', '2026-11-11 16:38:09'),
(34, 9, 67, 'Theo Bộ luật Hình sự 2015, hành vi “giết người” thuộc tội danh nào?', NULL, 'single_choice', 2.00, 0, 'Bộ luật Hình sự 2015 quy định “giết người” là tội danh thuộc mục 1, Điều 123. Các mục và điều khác đề cập đến các hành vi phạm pháp khác (cố ý gây thương tích, vi phạm an ninh trật tự, trộm cắp tài sản).\n---', NULL, '2026-11-09 09:27:07', '2026-11-11 16:37:57'),
(35, 9, 67, 'Trong hệ thống pháp luật, “luật lệ” (customary law) được công nhận và áp dụng trong những trường hợp nào?', NULL, 'single_choice', 2.00, 0, 'Luật lệ (customary law) chỉ được áp dụng khi không có quy định nào trong các văn bản pháp luật chính (luật, pháp lệnh, nghị định, quyết định). Khi có quy định pháp luật, luật lệ không được ưu tiên. Các đáp án B, C, D không đúng.\n---', NULL, '2026-11-09 09:27:07', '2026-11-11 16:37:35'),
(36, 9, 67, 'Người dân có quyền gì khi bị cơ quan hành chính ra quyết định không có căn cứ pháp lý?', NULL, 'single_choice', 2.00, 0, 'Khi quyết định hành chính không có căn cứ pháp lý, người dân có quyền khởi kiện ra tòa án (đơn kiện hành chính) để yêu cầu tòa án hủy bỏ hoặc sửa đổi quyết định. Đây là quyền bảo vệ pháp lý của công dân. Các đáp án A, C, D vi phạm quyền khiếu nại và khởi kiện của công dân.', NULL, '2026-11-09 09:27:07', '2026-11-11 16:37:20'),
(37, 9, 64, 'Biến đổi khí hậu đang gây ra hiện tượng tan chảy băng ở Bắc Cực. Khi khối lượng băng tan giảm, mức nước biển toàn cầu dự kiến sẽ tăng bao nhiêu mét vào cuối thế kỷ 21 (theo các kịch bản IPCC trung bình)?', NULL, 'single_choice', 2.00, 0, 'Các kịch bản trung bình của IPCC (RCP4.5) ước tính mức tăng trung bình khoảng 0,6 m – 0,9 m so với mức hiện tại nếu không có biện pháp giảm phát thải mạnh.\n---', NULL, '2026-11-09 09:29:28', '2026-11-11 16:36:26'),
(38, 9, 64, 'Trong hệ thống sông lớn của Việt Nam, sông nào có lưu vực rộng nhất?', NULL, 'single_choice', 2.00, 0, 'Lưu vực sông Cửu Long (Mekong) bao phủ hơn 800 000 km², chiếm khoảng 70 % diện tích đồng bằng sông Cửu Long, lớn hơn hẳn lưu vực sông Hồng (≈ 67 000 km²) và các lưu vực khác.\n---', NULL, '2026-11-09 09:29:28', '2026-11-11 16:33:03'),
(39, 9, 64, 'Địa hình nào chiếm diện tích lớn nhất trên lãnh thổ Việt Nam?', NULL, 'single_choice', 2.00, 0, 'Khoảng 80 % diện tích đất liền Việt Nam là núi non, trong đó đa số là các dãy núi và đồi thuộc hệ thống dãy Trường Sơn, dãy Hoành Sơn, dãy Bạch Mã… Đồng bằng chiếm khoảng 15 % và cao nguyên chỉ khoảng 5 %.\n---', NULL, '2026-11-09 09:29:28', '2026-11-11 16:32:36'),
(40, 9, 64, 'Khu vực nào sau đây là “điểm nóng” của bão nhiệt đới ở khu vực Tây Thái Bình Dương?', NULL, 'single_choice', 2.00, 0, 'Phía tây Thái Bình Dương (đặc biệt là quần đảo Philippines) là khu vực có tần suất bão nhiệt đới cao nhất do vị trí nằm trong “vòng bão” (tropical cyclone belt) và có nguồn nhiệt, độ ẩm dồi dào.\n---', NULL, '2026-11-09 09:29:28', '2026-11-11 16:32:07'),
(41, 9, 64, 'Trong bản đồ địa hình, ký hiệu “▲” thường dùng để biểu thị:', NULL, 'single_choice', 2.00, 0, 'Ký hiệu “▲” (tam giác) trong bản đồ địa hình đại diện cho đỉnh núi hoặc đồi, thường đi kèm với độ cao (mét) được ghi bên cạnh. Các ký hiệu khác: “●” cho đảo, “■” cho hồ, “▭” cho đồng cỏ.\n---\n*Ghi chú:* Các câu hỏi đã được viết theo chuẩn EduTest, dễ sao chép trực tiếp vào ngân hàng câu hỏi của hệ thống EduTest.', NULL, '2026-11-09 09:29:28', '2026-11-11 16:31:43'),
(42, 9, 61, 'Trong cuộc kháng chiến chống Pháp, “Ngày 9‑9” được xem là ngày khởi đầu của cuộc khởi nghĩa nào?', NULL, 'single_choice', 2.00, 0, 'Ngày 9 / 9 1945 là ngày Chủ tịch Hồ Chí Minh đọc Thông báo độc lập, đánh dấu khởi đầu của cuộc kháng chiến chống Pháp và mở ra giai đoạn đấu tranh giành độc lập.\n---', NULL, '2026-11-09 09:29:43', '2026-11-11 16:31:19'),
(43, 9, 61, 'Người sáng lập Đảng Cộng sản Việt Nam là:', NULL, 'single_choice', 2.00, 0, 'Hồ Chí Minh được coi là người sáng lập Đảng Cộng sản Việt Nam (được thành lập chính thức vào ngày 3 / 6 1930), đồng thời là lãnh tụ của phong trào cách mạng Việt Nam.\n---', NULL, '2026-11-09 09:29:43', '2026-11-11 16:31:04'),
(44, 9, 61, 'Trong thời kỳ Đế quốc Hán, “điều luật” nào được coi là quyển luật pháp đầu tiên của Trung Quốc?', NULL, 'single_choice', 2.00, 0, 'Luật Lý (Lý Luật) là quyển luật pháp đầu tiên của Đế quốc Hán, quy định các quy tắc về hành chính, pháp lý và quản lý đất đai.\n---', NULL, '2026-11-09 09:29:43', '2026-11-11 16:30:47'),
(45, 9, 61, 'Sự kiện “Đại hội Đại học 1975” tại Hà Nội có ý nghĩa gì?', NULL, 'single_choice', 2.00, 0, 'Đại hội Đại học 1975 (đại hội 1) tại Hà Nội là nơi chính thức tuyên bố thống nhất hai miền Việt Nam, thiết lập nền chính trị và xã hội mới cho đất nước.\n---', NULL, '2026-11-09 09:29:43', '2026-11-11 16:30:30'),
(47, 9, 49, 'Choose the correct form of the verb to complete the sentence.\n“The teacher _____ the students to submit their assignments by Friday.”', NULL, 'single_choice', 2.00, 0, 'Câu nói về một yêu cầu sẽ được đưa ra trong tương lai, vì vậy cần dùng thì tương lai đơn “will ask”. Các dạng “asks” (hiện tại), “asked” (quá khứ) và “asking” (dạng V‑ing) không phù hợp với ngữ cảnh thời gian.\n---', NULL, '2026-11-09 09:30:20', '2026-11-11 16:29:58'),
(48, 9, 49, 'Which word is a synonym of “elaborate” in the following sentence?\n“The scientist gave an elaborate explanation of the experiment.”', NULL, 'single_choice', 2.00, 0, '“Elaborate” có nghĩa là “chi tiết, tỉ mỉ”. Trong câu, nó mô tả cách giải thích của nhà khoa học, vì vậy từ đồng nghĩa là “detailed”. Các đáp án còn lại mang nghĩa ngược lại.\n---', NULL, '2026-11-09 09:30:20', '2026-11-11 16:21:23'),
(49, 9, 49, 'Choose the sentence that uses the correct comparative form.', NULL, 'single_choice', 2.00, 0, 'Khi so sánh hai đối tượng, tính từ “interesting” (đúng) dùng dạng “more + tính từ”. Các đáp án B, C, D sai về cấu trúc so sánh.\n---', NULL, '2026-11-09 09:30:20', '2026-11-11 16:21:05'),
(50, 9, 49, 'Read the short passage and answer the question.\n*Passage:*\n“During the summer holidays, Maya decided to volunteer at the local animal shelter. She spent her mornings feeding the dogs and her afternoons helping the staff clean the cages. By the end of the month, the shelter’s adoption rate had increased by 15 %.”\nQuestion: What is the most likely reason the adoption rate increased?', NULL, 'single_choice', 2.00, 0, 'Đoạn văn nhấn mạnh rằng Maya đã chăm sóc và làm sạch chuồng, giúp các con vật khỏe mạnh và sạch sẽ, điều này thường làm tăng khả năng được nhận nuôi. Các lựa chọn A, C, D không được đề cập trong đoạn văn.\n---', NULL, '2026-11-09 09:30:20', '2026-11-11 16:20:53'),
(51, 9, 49, 'Choose the sentence that is punctuated correctly.', NULL, 'single_choice', 2.00, 0, 'Khi liệt kê bốn hoặc nhiều hơn các mục, cần dùng dấu phẩy giữa các mục và dấu phẩy Oxford (trước “and”) là tùy chọn nhưng ở đây được dùng đúng. Các đáp án A, C, D có lỗi về vị trí dấu phẩy hoặc thiếu dấu phẩy.\n---\n*Lưu ý:* Các câu hỏi đã được viết theo chuẩn EduTest, dễ sao chép vào ngân hàng câu hỏi của hệ thống EduTest.', NULL, '2026-11-09 09:30:20', '2026-11-11 16:20:36'),
(52, 9, 58, 'Trong một tế bào thực vật, bào quan nào chịu trách nhiệm tổng hợp protein?', NULL, 'single_choice', 2.00, 0, 'Ribosome là bào quan không màng, nằm rải rác trong tế bào hoặc gắn vào mạng lưới nội chất (ER). Chức năng chính của ribosome là tổng hợp protein dựa trên thông tin di truyền từ mRNA. Lục lạp thực hiện quang hợp, ty thể chịu trách nhiệm hô hấp tế bào, thể chất dùng để lưu trữ.\n---', NULL, '2026-11-09 09:30:41', '2026-11-11 16:19:48'),
(53, 9, 59, 'Quá trình quang hợp ở thực vật có thể tóm tắt bằng phương trình tổng quát:\n6 CO₂ + 6 H₂O → C₆H₁₂O₆ + 6 O₂\nTrong phương trình trên, năng lượng ánh sáng được chuyển đổi thành dạng nào?', NULL, 'single_choice', 2.00, 0, 'Ở giai đoạn phản ứng sáng (light‑dependent reactions) của quang hợp, năng lượng ánh sáng được hấp thụ bởi lục lạp và chuyển đổi thành năng lượng hoá học dưới dạng ATP và NADPH. Những chất năng lượng này sau đó được dùng trong giai đoạn phản ứng tối (Calvin cycle) để tổng hợp glucose (C₆H₁₂O₆).\n---', NULL, '2026-11-09 09:30:41', '2026-11-11 16:19:18'),
(54, 9, 59, 'Trong ống tiêu hoá người, chức năng chính của dạ dày là gì?', NULL, 'single_choice', 2.00, 0, 'Dạ dày tiết dịch dạ dày chứa acid clohydric (HCl) làm môi trường pH thấp, đồng thời tiết enzyme pepsin (được kích hoạt trong môi trường axit) để phá vỡ liên kết peptide của protein. Enzyme amylase chủ yếu hoạt động trong nước bọt và tụy, không phải ở dạ dày. Việc hấp thu chất dinh dưỡng chủ yếu diễn ra ở ruột non, còn chất béo được tiêu hoá bằng mật và enzyme lipase từ tụy.', NULL, '2026-11-09 09:30:41', '2026-11-11 16:18:41'),
(55, 9, 46, 'Trong tác phẩm “Chiếc thuyền ngoài xa” của Nguyễn Minh Châu, hình ảnh “chiếc thuyền” được dùng để biểu hiện ý nghĩa gì?', NULL, 'single_choice', 2.00, 0, '“Chiếc thuyền” trong truyện không chỉ là một phương tiện di chuyển mà còn là biểu tượng của khát vọng sống, của ước mơ vươn lên, của ánh sáng hy vọng xuyên qua “bóng tối” của chiến tranh và nghịch cảnh.\n---', NULL, '2026-11-09 09:30:58', '2026-11-11 16:18:00'),
(56, 9, 46, '“Văn học hiện thực” ở Việt Nam bắt đầu phát triển mạnh mẽ từ thời kỳ nào?', NULL, 'single_choice', 2.00, 0, 'Văn học hiện thực ở Việt Nam nở rộ trong thời kỳ cách mạng (thập niên 1930‑1940) với những tác phẩm của Nam Cao, Tô Hoài, Nguyễn Tuân… Thể hiện hiện thực xã hội, con người và đấu tranh cách mạng.\n---', NULL, '2026-11-09 09:30:58', '2026-11-11 16:17:45'),
(57, 9, 46, 'Trong thơ “Bến xuân” của Huy Cận, hình ảnh “bến” được dùng để ám chỉ:', NULL, 'single_choice', 2.00, 0, '“Bến xuân” là hình ảnh thơ mộng, lãng mạn, tượng trưng cho nơi chờ đợi, nơi người yêu hẹn hò, gợi lên cảm giác nhớ mong và hy vọng được gặp lại người thương trong không gian mùa xuân tươi đẹp.', NULL, '2026-11-09 09:30:58', '2026-11-11 16:17:30'),
(58, 9, 52, 'Một vật chuyển động thẳng với vận tốc ban đầu v₀ = 5   m/s và gia tốc không đổi a = 2   m/s². Sau thời gian t = 4   s vật di chuyển được quãng đường bao nhiêu?', NULL, 'single_choice', 2.00, 0, 'Quãng đường s = v₀ t + 1/2 a t² = 5·4 + 1/2·2·4² = 20 + 16 = 36   m.\n---', NULL, '2026-11-10 15:35:49', '2026-11-11 16:17:13'),
(59, 9, 52, 'Một vật bắt đầu chuyển động từ trạng thái nghỉ (v₀ = 0) với gia tốc a = 3   m/s². Khi vật đã di chuyển được quãng đường s = 27   m, vận tốc của nó là bao nhiêu?', NULL, 'single_choice', 2.00, 0, 'Dùng công thức v² = v₀² + 2 a s.\nv = √(0 + 2·3·27) = √162 = 12.73\\ldots ≈ 12   m/s (làm tròn tới số nguyên gần nhất).\n---', NULL, '2026-11-10 15:35:50', '2026-11-11 16:16:53'),
(60, 9, 52, 'Xe ô tô đang chạy với vận tốc v₀ = 20   m/s và phanh để dừng hẳn trong quãng đường s = 50   m. Gia tốc (không âm) của quá trình phanh là:', NULL, 'single_choice', 2.00, 0, 'Vì xe dừng, v = 0. Dùng v² = v₀² + 2 a s → 0 = 20² + 2 a·50.\n2 a·50 = -400 → a = -400 / 100 = -4   m/s².\n---', NULL, '2026-11-10 15:35:50', '2026-11-11 16:16:33'),
(61, 11, 52, 'Một ô tô xuất phát từ trạng thái nghỉ, chuyển động thẳng biến đổi đều với gia tốc a = 2 m/s² trong thời gian t = 5 s. Quãng đường ô tô đi được trong khoảng thời gian này là bao nhiêu?', NULL, 'single_choice', 2.00, 1, 'Quãng đường s = v₀·t + ½·a·t² (v₀ = 0 vì xuất phát từ nghỉ)\ns = ½·2·5² = 1·25 = 25 m.\n---', NULL, '2026-11-18 14:27:56', '2026-11-18 14:27:56'),
(62, 11, 52, 'Một vật chuyển động thẳng biến đổi đều với gia tốc a = 3 m/s² và vận tốc ban đầu v₀ = 4 m/s. Khi vật đã di chuyển được quãng đường s = 20 m, vận tốc của nó bằng bao nhiêu?', NULL, 'single_choice', 2.00, 2, 'Dùng công thức v² = v₀² + 2·a·s\nv² = 4² + 2·3·20 = 16 + 120 = 136 → v = √136 ≈ 11,66 m/s (làm tròn 11,7 m/s).\n---', NULL, '2026-11-18 14:27:56', '2026-11-18 14:27:56'),
(63, 11, 52, 'Một viên đá được ném thẳng lên trên với vận tốc ban đầu v₀ = 20 m/s. Lấy gia tốc trọng trường g = 10 m/s² (hướng xuống). Thời gian để viên đá đạt độ cao cực đại là bao nhiêu?', NULL, 'single_choice', 2.00, 3, 'Ở độ cao cực đại, vận tốc cuối cùng v = 0.\nv = v₀ – g·t → 0 = 20 – 10·t → t = 20/10 = 2 s.\n---\n*Các câu hỏi trên đã được định dạng theo chuẩn EduTest: nội dung rõ ràng, công thức viết bằng ký hiệu Unicode, 4 đáp án A‑D, chỉ ra đáp án đúng và kèm giải thích ngắn gọn.*', NULL, '2026-11-18 14:27:56', '2026-11-18 14:27:56'),
(64, 11, 52, 'Một vật chuyển động thẳng với vận tốc ban đầu v₀ = 5   m/s và gia tốc không đổi a = 2   m/s². Sau thời gian t = 4   s vật di chuyển được quãng đường bao nhiêu?', NULL, 'single_choice', 2.00, 4, 'Quãng đường s = v₀ t + 1/2 a t² = 5·4 + 1/2·2·4² = 20 + 16 = 36   m.\n---', NULL, '2026-11-18 14:27:56', '2026-11-18 14:27:56'),
(65, 11, 52, 'Một vật bắt đầu chuyển động từ trạng thái nghỉ (v₀ = 0) với gia tốc a = 3   m/s². Khi vật đã di chuyển được quãng đường s = 27   m, vận tốc của nó là bao nhiêu?', NULL, 'single_choice', 2.00, 5, 'Dùng công thức v² = v₀² + 2 a s.\nv = √(0 + 2·3·27) = √162 = 12.73\\ldots ≈ 12   m/s (làm tròn tới số nguyên gần nhất).\n---', NULL, '2026-11-18 14:27:56', '2026-11-18 14:27:56'),
(66, 11, 52, 'Xe ô tô đang chạy với vận tốc v₀ = 20   m/s và phanh để dừng hẳn trong quãng đường s = 50   m. Gia tốc (không âm) của quá trình phanh là:', NULL, 'single_choice', 2.00, 6, 'Vì xe dừng, v = 0. Dùng v² = v₀² + 2 a s → 0 = 20² + 2 a·50.\n2 a·50 = -400 → a = -400 / 100 = -4   m/s².\n---', NULL, '2026-11-18 14:27:56', '2026-11-18 14:27:56'),
(67, 12, 49, 'Choose the correct form of the verb to complete the sentence.\n“The teacher _____ the students to submit their assignments by Friday.”', NULL, 'single_choice', 2.00, 1, 'Câu nói về một yêu cầu sẽ được đưa ra trong tương lai, vì vậy cần dùng thì tương lai đơn “will ask”. Các dạng “asks” (hiện tại), “asked” (quá khứ) và “asking” (dạng V‑ing) không phù hợp với ngữ cảnh thời gian.\n---', NULL, '2026-11-18 14:28:58', '2026-11-18 14:28:58'),
(68, 12, 49, 'Which word is a synonym of “elaborate” in the following sentence?\n“The scientist gave an elaborate explanation of the experiment.”', NULL, 'single_choice', 2.00, 2, '“Elaborate” có nghĩa là “chi tiết, tỉ mỉ”. Trong câu, nó mô tả cách giải thích của nhà khoa học, vì vậy từ đồng nghĩa là “detailed”. Các đáp án còn lại mang nghĩa ngược lại.\n---', NULL, '2026-11-18 14:28:58', '2026-11-18 14:28:58'),
(69, 12, 49, 'Choose the sentence that uses the correct comparative form.', NULL, 'single_choice', 2.00, 3, 'Khi so sánh hai đối tượng, tính từ “interesting” (đúng) dùng dạng “more + tính từ”. Các đáp án B, C, D sai về cấu trúc so sánh.\n---', NULL, '2026-11-18 14:28:58', '2026-11-18 14:28:58'),
(70, 12, 49, 'Read the short passage and answer the question.\n*Passage:*\n“During the summer holidays, Maya decided to volunteer at the local animal shelter. She spent her mornings feeding the dogs and her afternoons helping the staff clean the cages. By the end of the month, the shelter’s adoption rate had increased by 15 %.”\nQuestion: What is the most likely reason the adoption rate increased?', NULL, 'single_choice', 2.00, 4, 'Đoạn văn nhấn mạnh rằng Maya đã chăm sóc và làm sạch chuồng, giúp các con vật khỏe mạnh và sạch sẽ, điều này thường làm tăng khả năng được nhận nuôi. Các lựa chọn A, C, D không được đề cập trong đoạn văn.\n---', NULL, '2026-11-18 14:28:58', '2026-11-18 14:28:58'),
(71, 12, 49, 'Choose the sentence that is punctuated correctly.', NULL, 'single_choice', 2.00, 5, 'Khi liệt kê bốn hoặc nhiều hơn các mục, cần dùng dấu phẩy giữa các mục và dấu phẩy Oxford (trước “and”) là tùy chọn nhưng ở đây được dùng đúng. Các đáp án A, C, D có lỗi về vị trí dấu phẩy hoặc thiếu dấu phẩy.\n---\n*Lưu ý:* Các câu hỏi đã được viết theo chuẩn EduTest, dễ sao chép vào ngân hàng câu hỏi của hệ thống EduTest.', NULL, '2026-11-18 14:28:58', '2026-11-18 14:28:58'),
(72, 13, 46, 'Trong tác phẩm “Chiếc thuyền ngoài xa” của Nguyễn Minh Châu, hình ảnh “chiếc thuyền” được dùng để biểu hiện ý nghĩa gì?', NULL, 'single_choice', 2.00, 1, '“Chiếc thuyền” trong truyện không chỉ là một phương tiện di chuyển mà còn là biểu tượng của khát vọng sống, của ước mơ vươn lên, của ánh sáng hy vọng xuyên qua “bóng tối” của chiến tranh và nghịch cảnh.\n---', NULL, '2026-11-18 14:32:01', '2026-11-18 14:32:01'),
(73, 13, 46, '“Văn học hiện thực” ở Việt Nam bắt đầu phát triển mạnh mẽ từ thời kỳ nào?', NULL, 'single_choice', 2.00, 2, 'Văn học hiện thực ở Việt Nam nở rộ trong thời kỳ cách mạng (thập niên 1930‑1940) với những tác phẩm của Nam Cao, Tô Hoài, Nguyễn Tuân… Thể hiện hiện thực xã hội, con người và đấu tranh cách mạng.\n---', NULL, '2026-11-18 14:32:01', '2026-11-18 14:32:01'),
(74, 13, 46, 'Trong thơ “Bến xuân” của Huy Cận, hình ảnh “bến” được dùng để ám chỉ:', NULL, 'single_choice', 2.00, 3, '“Bến xuân” là hình ảnh thơ mộng, lãng mạn, tượng trưng cho nơi chờ đợi, nơi người yêu hẹn hò, gợi lên cảm giác nhớ mong và hy vọng được gặp lại người thương trong không gian mùa xuân tươi đẹp.', NULL, '2026-11-18 14:32:01', '2026-11-18 14:32:01'),
(75, 14, 58, 'Trong một tế bào thực vật, bào quan nào chịu trách nhiệm tổng hợp protein?', NULL, 'single_choice', 2.00, 1, 'Ribosome là bào quan không màng, nằm rải rác trong tế bào hoặc gắn vào mạng lưới nội chất (ER). Chức năng chính của ribosome là tổng hợp protein dựa trên thông tin di truyền từ mRNA. Lục lạp thực hiện quang hợp, ty thể chịu trách nhiệm hô hấp tế bào, thể chất dùng để lưu trữ.\n---', NULL, '2026-11-18 14:33:32', '2026-11-18 14:33:32'),
(76, 9, 55, 'Phản ứng giữa kim loại kiềm Na và nước cho ra sản phẩm nào?', NULL, 'single_choice', 2.00, 0, 'Na + H₂O → NaOH + H₂ (phản ứng mạnh, tạo kiềm và khí hydro).\n---', NULL, '2026-11-18 14:36:21', '2026-11-18 14:36:21'),
(77, 9, 55, 'Trong bảng tuần hoàn, nguyên tử nào có bán kính cộng điện tử lớn nhất?', NULL, 'single_choice', 2.00, 0, 'Bán kính cộng điện tử tăng dần từ trên xuống dưới cùng một nhóm; Rb (nhóm 1) lớn nhất trong các lựa chọn.\n---', NULL, '2026-11-18 14:36:21', '2026-11-18 14:36:21'),
(78, 9, 55, 'Phản ứng trung hòa giữa HCl và NaOH được viết như thế nào?', NULL, 'single_choice', 2.00, 0, 'Phản ứng axit-bazơ tạo muối và nước (HCl + NaOH → NaCl + H₂O).\n---', NULL, '2026-11-18 14:36:21', '2026-11-18 14:36:21'),
(79, 9, 55, 'Đối với phản ứng: 2 Mg + O₂ → 2 MgO, khối lượng MgO tạo thành khi 5 g Mg phản ứng hoàn toàn là bao nhiêu? (M(Mg)=24 g mol⁻¹, M(MgO)=40 g mol⁻¹)', NULL, 'single_choice', 2.00, 0, 'Số mol Mg = 5 g / 24 g mol⁻¹ = 0,208 mol. Theo tỉ lệ 2 mol Mg → 2 mol MgO, nên n(MgO)=0,208 mol. Khối lượng MgO = 0,208 mol × 40 g mol⁻¹ = 8,33 g. Tuy nhiên vì phản ứng viết 2 Mg → 2 MgO, khối lượng MgO = (5 g × 40) / 24 = 8,33 g → gần nhất là A. *(Lưu ý: Đáp án A là đúng; đã sửa lại đáp án trong phần giải thích)*\n---', NULL, '2026-11-18 14:36:21', '2026-11-18 14:36:21'),
(80, 9, 55, 'Đối với hợp chất C₂H₆O, các công thức cấu tạo khả dĩ là:', NULL, 'single_choice', 2.00, 0, 'C₂H₆O có 2 isomer cấu trúc: etanol (CH₃CH₂OH) và dimetyl ether (CH₃OCH₃).\n---', NULL, '2026-11-18 14:36:22', '2026-11-18 14:36:22'),
(81, 9, 55, 'Khi dung dịch NaClO₃ (0,1 M) được làm nóng, phản ứng phân hủy sinh ra khí nào?', NULL, 'single_choice', 2.00, 0, 'NaClO₃ → NaCl + 3 O₂ (phản ứng phân hủy tạo O₂).\n---', NULL, '2026-11-18 14:36:22', '2026-11-18 14:36:22'),
(82, 9, 55, 'Độ pH của dung dịch HCl 0,01 M là:', NULL, 'single_choice', 2.00, 0, 'pH = –log[H⁺] = –log(0,01) = 2 → nhưng vì HCl hoàn toàn phân ly, [H⁺] = 0,01 M → pH = 2. *Vậy đáp án A là đúng.* *(Sửa lại: Đáp án A)*\n---', NULL, '2026-11-18 14:36:22', '2026-11-18 14:36:22'),
(83, 9, 55, 'Phản ứng oxi hoá‑khử: 2 Fe²⁺ + H₂O₂ + 2 H⁺ → 2 Fe³⁺ + 2 H₂O. Trong phản ứng này, H₂O₂ đóng vai trò:', NULL, 'single_choice', 2.00, 0, 'H₂O₂ có thể nhận electron (khử) và cho electron (oxi hoá), ở đây vừa oxi hoá Fe²⁺ → Fe³⁺ vừa bị khử thành H₂O.\n---', NULL, '2026-11-18 14:36:22', '2026-11-18 14:36:22'),
(84, 9, 55, 'Khối lượng mol của CO₂ là bao nhiêu? (C=12 g mol⁻¹, O=16 g mol⁻¹)', NULL, 'single_choice', 2.00, 0, 'M(CO₂)=12 + 2×16 = 44 g mol⁻¹.\n---', NULL, '2026-11-18 14:36:22', '2026-11-18 14:36:22'),
(85, 9, 55, 'Khi dung dịch Na₂CO₃ (0,2 M) trộn với dung dịch HCl (0,2 M) đủ mol, sản phẩm thu được là:', NULL, 'single_choice', 2.00, 0, 'Phản ứng trung hòa + giải phóng CO₂: Na₂CO₃ + 2 HCl → 2 NaCl + H₂O + CO₂.\n---', NULL, '2026-11-18 14:36:22', '2026-11-18 14:36:22'),
(86, 9, 55, 'Trong các hợp chất sau, hợp chất nào là axit yếu?', NULL, 'single_choice', 2.00, 0, 'Axit acetic (CH₃COOH) có Ka ≈ 1,8×10⁻⁵, yếu hơn các axit mạnh HCl, H₂SO₄, HNO₃.\n---', NULL, '2026-11-18 14:36:22', '2026-11-18 14:36:22'),
(87, 9, 55, 'Đối với phản ứng: N₂ + 3 H₂ ⇌ 2 NH₃, nếu áp suất tổng tăng mà tỉ lệ phần trăm các chất không đổi, thì:', NULL, 'single_choice', 2.00, 0, 'Khi tỉ lệ phần trăm (phần trăm mol) của các chất không đổi, nghĩa là hệ đã đạt cân bằng mới; áp suất tăng làm tỉ lệ phần trăm thay đổi, vì vậy câu C là đúng khi tỉ lệ không đổi.\n---', NULL, '2026-11-18 14:36:22', '2026-11-18 14:36:22'),
(88, 9, 55, 'Trong các chất sau, chất nào có tính dẫn điện cao nhất trong dạng dung dịch?', NULL, 'single_choice', 2.00, 0, 'NaCl tan hoàn toàn, tạo Na⁺ và Cl⁻, dẫn điện mạnh. Các chất hữu cơ không ion hoá, dẫn điện kém.\n---', NULL, '2026-11-18 14:36:22', '2026-11-18 14:36:22'),
(89, 9, 55, 'Khi dung dịch NaOH 0,1 M được pha loãng thành 0,5 L, nồng độ mới là bao nhiêu?', NULL, 'single_choice', 2.00, 0, 'Số mol NaOH = C₁·V₁ = 0,1 M × 0,1 L = 0,01 mol (giả sử dung dịch ban đầu 0,1 L). Khi đưa vào 0,5 L, C₂ = 0,01 mol / 0,5 L = 0,02 M → đáp án A. *(Sửa lại: Đáp án A là đúng)*\n---', NULL, '2026-11-18 14:36:22', '2026-11-18 14:36:22'),
(90, 9, 55, 'Phản ứng nào sau đây là phản ứng trao đổi ion (đối đổi)?', NULL, 'single_choice', 2.00, 0, 'Hai muối hòa tan trao đổi ion tạo muối kém tan (AgCl) – đặc trưng cho phản ứng trao đổi ion.\n---\nII. GỢI Ý CẤU TRÚC ĐỀ THI\n| Phần | Số câu | Loại câu | Thời gian (phút) |\n|------|--------|----------|-------------------|\n| I    | 15     | Trắc nghiệm (A‑D) | 30 |\n| II   | 3      | Điền khuyết (công thức, cân bằng) | 15 |\n| III  | 2      | Tự luận ngắn (giải thích cơ chế, tính toán) | 15 |\n| Tổng | 20 | – | 60 |\nLưu ý khi soạn câu hỏi cho phần II & III:\n- Câu điền khuyết: Viết dưới dạng “_____” và ghi chú “đáp án: …” ở cuối đề (để giáo viên kiểm tra).\n- Câu tự luận: Đưa ra yêu cầu rõ ràng, ví dụ “Giải thích tại sao dung dịch NaClO₃ khi đun nóng sinh ra O₂” và yêu cầu viết công thức hoá học bằng Unicode (ví dụ: NaClO₃ → NaCl + 3 O₂).\n---\nIII. HƯỚNG DẪN SỬ DỤNG HỆ THỐNG EduTest\n1. Đăng nhập\n- Truy cập https://edutest.edu.vn → nhập tài khoản “Bùi Hoàng Dũng”.\n2. Tạo đề mới\n- Vào Quản lý đề thi → Thêm đề.\n- Điền tiêu đề (VD: “Đề Hóa học – Lớp 10 – 18/11/2026”), thời gian làm bài (60 phút), mức độ khó (đặt “Trung bình”).\n3. Nhập câu hỏi\n- Chọn Thêm câu hỏi → Loại: Trắc nghiệm.\n- Sao chép từng câu theo đúng định dạng (Câu X: …, A., B., C., D., Đáp án đúng: …, Giải thích: …).\n- Đảm bảo không có ký hiệu LaTeX; dùng Unicode (x², Δ, →,', NULL, '2026-11-18 14:36:22', '2026-11-18 14:36:22'),
(91, 15, 55, 'Phản ứng giữa kim loại kiềm Na và nước cho ra sản phẩm nào?', NULL, 'single_choice', 2.00, 1, 'Na + H₂O → NaOH + H₂ (phản ứng mạnh, tạo kiềm và khí hydro).\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(92, 15, 55, 'Trong bảng tuần hoàn, nguyên tử nào có bán kính cộng điện tử lớn nhất?', NULL, 'single_choice', 2.00, 2, 'Bán kính cộng điện tử tăng dần từ trên xuống dưới cùng một nhóm; Rb (nhóm 1) lớn nhất trong các lựa chọn.\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(93, 15, 55, 'Phản ứng trung hòa giữa HCl và NaOH được viết như thế nào?', NULL, 'single_choice', 2.00, 3, 'Phản ứng axit-bazơ tạo muối và nước (HCl + NaOH → NaCl + H₂O).\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(94, 15, 55, 'Đối với phản ứng: 2 Mg + O₂ → 2 MgO, khối lượng MgO tạo thành khi 5 g Mg phản ứng hoàn toàn là bao nhiêu? (M(Mg)=24 g mol⁻¹, M(MgO)=40 g mol⁻¹)', NULL, 'single_choice', 2.00, 4, 'Số mol Mg = 5 g / 24 g mol⁻¹ = 0,208 mol. Theo tỉ lệ 2 mol Mg → 2 mol MgO, nên n(MgO)=0,208 mol. Khối lượng MgO = 0,208 mol × 40 g mol⁻¹ = 8,33 g. Tuy nhiên vì phản ứng viết 2 Mg → 2 MgO, khối lượng MgO = (5 g × 40) / 24 = 8,33 g → gần nhất là A. *(Lưu ý: Đáp án A là đúng; đã sửa lại đáp án trong phần giải thích)*\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(95, 15, 55, 'Đối với hợp chất C₂H₆O, các công thức cấu tạo khả dĩ là:', NULL, 'single_choice', 2.00, 5, 'C₂H₆O có 2 isomer cấu trúc: etanol (CH₃CH₂OH) và dimetyl ether (CH₃OCH₃).\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(96, 15, 55, 'Khi dung dịch NaClO₃ (0,1 M) được làm nóng, phản ứng phân hủy sinh ra khí nào?', NULL, 'single_choice', 2.00, 6, 'NaClO₃ → NaCl + 3 O₂ (phản ứng phân hủy tạo O₂).\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(97, 15, 55, 'Độ pH của dung dịch HCl 0,01 M là:', NULL, 'single_choice', 2.00, 7, 'pH = –log[H⁺] = –log(0,01) = 2 → nhưng vì HCl hoàn toàn phân ly, [H⁺] = 0,01 M → pH = 2. *Vậy đáp án A là đúng.* *(Sửa lại: Đáp án A)*\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(98, 15, 55, 'Phản ứng oxi hoá‑khử: 2 Fe²⁺ + H₂O₂ + 2 H⁺ → 2 Fe³⁺ + 2 H₂O. Trong phản ứng này, H₂O₂ đóng vai trò:', NULL, 'single_choice', 2.00, 8, 'H₂O₂ có thể nhận electron (khử) và cho electron (oxi hoá), ở đây vừa oxi hoá Fe²⁺ → Fe³⁺ vừa bị khử thành H₂O.\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(99, 15, 55, 'Khối lượng mol của CO₂ là bao nhiêu? (C=12 g mol⁻¹, O=16 g mol⁻¹)', NULL, 'single_choice', 2.00, 9, 'M(CO₂)=12 + 2×16 = 44 g mol⁻¹.\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(100, 15, 55, 'Khi dung dịch Na₂CO₃ (0,2 M) trộn với dung dịch HCl (0,2 M) đủ mol, sản phẩm thu được là:', NULL, 'single_choice', 2.00, 10, 'Phản ứng trung hòa + giải phóng CO₂: Na₂CO₃ + 2 HCl → 2 NaCl + H₂O + CO₂.\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(101, 15, 55, 'Trong các hợp chất sau, hợp chất nào là axit yếu?', NULL, 'single_choice', 2.00, 11, 'Axit acetic (CH₃COOH) có Ka ≈ 1,8×10⁻⁵, yếu hơn các axit mạnh HCl, H₂SO₄, HNO₃.\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(102, 15, 55, 'Đối với phản ứng: N₂ + 3 H₂ ⇌ 2 NH₃, nếu áp suất tổng tăng mà tỉ lệ phần trăm các chất không đổi, thì:', NULL, 'single_choice', 2.00, 12, 'Khi tỉ lệ phần trăm (phần trăm mol) của các chất không đổi, nghĩa là hệ đã đạt cân bằng mới; áp suất tăng làm tỉ lệ phần trăm thay đổi, vì vậy câu C là đúng khi tỉ lệ không đổi.\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(103, 15, 55, 'Trong các chất sau, chất nào có tính dẫn điện cao nhất trong dạng dung dịch?', NULL, 'single_choice', 2.00, 13, 'NaCl tan hoàn toàn, tạo Na⁺ và Cl⁻, dẫn điện mạnh. Các chất hữu cơ không ion hoá, dẫn điện kém.\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(104, 15, 55, 'Khi dung dịch NaOH 0,1 M được pha loãng thành 0,5 L, nồng độ mới là bao nhiêu?', NULL, 'single_choice', 2.00, 14, 'Số mol NaOH = C₁·V₁ = 0,1 M × 0,1 L = 0,01 mol (giả sử dung dịch ban đầu 0,1 L). Khi đưa vào 0,5 L, C₂ = 0,01 mol / 0,5 L = 0,02 M → đáp án A. *(Sửa lại: Đáp án A là đúng)*\n---', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(105, 15, 55, 'Phản ứng nào sau đây là phản ứng trao đổi ion (đối đổi)?', NULL, 'single_choice', 2.00, 15, 'Hai muối hòa tan trao đổi ion tạo muối kém tan (AgCl) – đặc trưng cho phản ứng trao đổi ion.\n---\nII. GỢI Ý CẤU TRÚC ĐỀ THI\n| Phần | Số câu | Loại câu | Thời gian (phút) |\n|------|--------|----------|-------------------|\n| I    | 15     | Trắc nghiệm (A‑D) | 30 |\n| II   | 3      | Điền khuyết (công thức, cân bằng) | 15 |\n| III  | 2      | Tự luận ngắn (giải thích cơ chế, tính toán) | 15 |\n| Tổng | 20 | – | 60 |\nLưu ý khi soạn câu hỏi cho phần II & III:\n- Câu điền khuyết: Viết dưới dạng “_____” và ghi chú “đáp án: …” ở cuối đề (để giáo viên kiểm tra).\n- Câu tự luận: Đưa ra yêu cầu rõ ràng, ví dụ “Giải thích tại sao dung dịch NaClO₃ khi đun nóng sinh ra O₂” và yêu cầu viết công thức hoá học bằng Unicode (ví dụ: NaClO₃ → NaCl + 3 O₂).\n---\nIII. HƯỚNG DẪN SỬ DỤNG HỆ THỐNG EduTest\n1. Đăng nhập\n- Truy cập https://edutest.edu.vn → nhập tài khoản “Bùi Hoàng Dũng”.\n2. Tạo đề mới\n- Vào Quản lý đề thi → Thêm đề.\n- Điền tiêu đề (VD: “Đề Hóa học – Lớp 10 – 18/11/2026”), thời gian làm bài (60 phút), mức độ khó (đặt “Trung bình”).\n3. Nhập câu hỏi\n- Chọn Thêm câu hỏi → Loại: Trắc nghiệm.\n- Sao chép từng câu theo đúng định dạng (Câu X: …, A., B., C., D., Đáp án đúng: …, Giải thích: …).\n- Đảm bảo không có ký hiệu LaTeX; dùng Unicode (x², Δ, →,', NULL, '2026-11-18 14:36:46', '2026-11-18 14:36:46'),
(106, 9, 64, 'Ký hiệu địa lý “°N” và “°E” dùng để chỉ:', NULL, 'single_choice', 2.00, 0, '“°N” (bắc) và “°E” (đông) là đơn vị đo vĩ độ và kinh độ trong hệ tọa độ địa lý.\n---', NULL, '2026-11-18 14:37:31', '2026-11-18 14:37:31'),
(107, 9, 64, 'Địa hình nào chiếm diện tích lớn nhất trên lãnh thổ Việt Nam?', NULL, 'single_choice', 2.00, 0, 'Khoảng 80 % diện tích đất liền Việt Nam là núi non, trong khi đồng bằng chỉ chiếm khoảng 15 %.\n---', NULL, '2026-11-18 14:37:31', '2026-11-18 14:37:31'),
(108, 9, 64, 'Sông nào được gọi là “sông xanh” vì màu nước trong xanh, chảy qua miền Tây Nam Bộ?', NULL, 'single_choice', 2.00, 0, 'Sông Cửu Long (Mekong) có màu nước trong xanh, đặc biệt ở các khu vực đồng bằng sông Cửu Long, nên được dân địa phương gọi là “sông xanh”.\n---', NULL, '2026-11-18 14:37:31', '2026-11-18 14:37:31'),
(109, 9, 64, 'Địa danh “Hạ Long” thuộc tỉnh nào?', NULL, 'single_choice', 2.00, 0, 'Vịnh Hạ Long nằm trong tỉnh Quảng Ninh, là di sản thiên nhiên thế giới.\n---', NULL, '2026-11-18 14:37:31', '2026-11-18 14:37:31'),
(110, 9, 64, 'Ký hiệu “°C” trong bản đồ địa lý thường dùng để chỉ:', NULL, 'single_choice', 2.00, 0, 'Trên bản đồ địa hình, các đường đồng mức (contour) thường được ghi kèm độ cao tính bằng mét (m) hoặc độ (°), ví dụ 500 m hoặc 500 ° (độ cao).\n---', NULL, '2026-11-18 14:37:31', '2026-11-18 14:37:31'),
(111, 9, 64, 'Trong chu kỳ nước, quá trình “thẩm thấu” (evaporation) xảy ra ở:', NULL, 'single_choice', 2.00, 0, 'Thẩm thấu là quá trình bốc hơi nước từ bề mặt các nguồn nước (đại dương, sông, hồ) lên không khí.\n---', NULL, '2026-11-18 14:37:31', '2026-11-18 14:37:31'),
(112, 9, 64, 'Khu vực nào được xem là “điểm nóng” bão nhiệt đới ở Tây Thái Bình Dương?', NULL, 'single_choice', 2.00, 0, 'Vùng Tây Thái Bình Dương, đặc biệt là quần đảo Philippines, có tần suất bão nhiệt đới cao nhất do vị trí nằm trong “vòng bão” (tropical cyclone belt).\n---', NULL, '2026-11-18 14:37:31', '2026-11-18 14:37:31'),
(113, 9, 64, 'Trong hệ thống thời tiết, ký hiệu “⛅” thường biểu thị:', NULL, 'single_choice', 2.00, 0, '“⛅” là biểu tượng thời tiết cho “nắng có mây” (cloudy with sunshine).\n---', NULL, '2026-11-18 14:37:31', '2026-11-18 14:37:31'),
(114, 9, 64, 'Địa hình “đồi” thường có độ dốc:', NULL, 'single_choice', 2.00, 0, 'Đồi thường có độ dốc nhẹ, dao động từ 5 % đến 15 %.\n---', NULL, '2026-11-18 14:37:32', '2026-11-18 14:37:32'),
(115, 9, 64, 'Trong bản đồ địa lý, ký hiệu “△” thường dùng để chỉ:', NULL, 'single_choice', 2.00, 0, '“△” (tam giác) là ký hiệu chuẩn cho đỉnh núi hoặc đồi trên bản đồ địa hình.\n---', NULL, '2026-11-18 14:37:32', '2026-11-18 14:37:32'),
(116, 9, 64, 'Địa danh “Tam Đảo” nổi tiếng với:', NULL, 'single_choice', 2.00, 0, 'Tam Đảo (Hà Nội) là khu du lịch sinh thái với khí hậu ôn hòa, rừng thông và thác nước.\n---', NULL, '2026-11-18 14:37:32', '2026-11-18 14:37:32'),
(117, 9, 64, 'Trong hệ thống khí hậu Köppen, mã “Aw” biểu thị:', NULL, 'single_choice', 2.00, 0, '“Aw” trong Köppen là khí hậu nhiệt đới gió mùa, có mùa khô rõ rệt (savanna).\n---', NULL, '2026-11-18 14:37:32', '2026-11-18 14:37:32'),
(118, 9, 64, 'Khi một khu vực có “độ ẩm tương đối” cao (≥ 80 %), thường xảy ra hiện tượng gì?', NULL, 'single_choice', 2.00, 0, 'Độ ẩm cao tạo điều kiện cho sương mù và mưa phùn xuất hiện, nhất là vào buổi sáng sớm.\n---', NULL, '2026-11-18 14:37:32', '2026-11-18 14:37:32'),
(119, 9, 64, 'Trong lớp địa lý, “địa hình đồng bằng” thường có đặc điểm nào sau đây?', NULL, 'single_choice', 2.00, 0, 'Đồng bằng có độ dốc rất nhẹ, thường dưới 2 % và độ cao trung bình thấp.\n---', NULL, '2026-11-18 14:37:32', '2026-11-18 14:37:32'),
(120, 9, 64, '“Địa hình karst” (địa hình thạch nhũ) đặc trưng bởi:', NULL, 'single_choice', 2.00, 0, 'Karst là địa hình hình thành trên đá vôi, có các đặc điểm như hang động, mương, thạch nhũ, thường xuất hiện ở các khu vực như Quảng Bình, Huế.\n---\nII. GỢI Ý CẤU TRÚC ĐỀ THI ĐỊA LÝ\n| Phần | Số câu | Loại câu | Thời gian (phút) |\n|------|--------|----------|-------------------|\n| I    | 15     | Trắc nghiệm (A‑D) | 30 |\n| II   | 3      | Điền khuyết (đánh dấu “_____”) | 10 |\n| III  | 2      | Tự luận ngắn (phân tích bản đồ, giải thích hiện tượng) | 20 |\n| Tổng | 20 | – | 60 |\nLưu ý khi soạn câu hỏi cho phần II & III:\n- Câu điền khuyết: Viết dạng “_____” và ghi chú đáp án ở cuối đề (để giáo viên kiểm tra).\n- Câu tự luận: Yêu cầu rõ ràng, ví dụ: “Giải thích tại sao khu vực miền Trung Việt Nam có mùa mưa kéo dài hơn miền Bắc” và yêu cầu đưa ra các yếu tố khí hậu, địa hình, gió mùa.\n---\nIII. HƯỚNG DẪN SỬ DỤNG HỆ THỐNG EduTest (đối với giáo viên Bùi Hoàng Dũng)\n1. Đăng nhập\n- Truy cập https://edutest.edu.vn → nhập tài khoản giáo viên.\n2. Tạo đề mới\n- Vào Quản lý đề thi → Thêm đề.\n- Điền tiêu đề (VD: “Đề Địa lý – Lớp 10 – 18/11/2026”), thời gian làm bài (60 phút), mức độ khó (“Trung bình”).\n3. Nhập câu hỏi\n- Chọn Thêm câu hỏi → Loại: Trắc nghiệm.\n- Sao chép từng câu theo đúng định dạng (Câu X: …, A., B., C., D., Đáp án đúng: …, Giải thích: …).\n- Đối với câu điền khuyết và tự luận, chọn loại “Điền khuyết” hoặc “Tự luận” tương ứng và nhập nội dung.\n4. Kiểm tra và lưu\n- Sau khi nhập xong, nhấn Xem trước để chắc chắn định dạng hiển thị đúng (không có ký hiệu LaTeX, chỉ Unicode).\n- Nhấn Lưu → Phát hành cho lớp hoặc cho học sinh cụ thể.\n5. Theo dõi kết quả\n- Vào Bảng điểm → Chi tiết để xem từng câu trả lời, thời gian làm bài, và thống kê mức độ khó của câu hỏi.\n---\n*Bạn có thể sao chép toàn bộ các câu hỏi trên vào ngân hàng câu hỏi của EduTest và tùy chỉnh lại số lượng, độ khó hoặc thêm hình ảnh bản đồ (định dạng PNG/JPEG) nếu cần.*', NULL, '2026-11-18 14:37:32', '2026-11-18 14:37:32'),
(121, 16, 64, 'Biến đổi khí hậu đang gây ra hiện tượng tan chảy băng ở Bắc Cực. Khi khối lượng băng tan giảm, mức nước biển toàn cầu dự kiến sẽ tăng bao nhiêu mét vào cuối thế kỷ 21 (theo các kịch bản IPCC trung bình)?', NULL, 'single_choice', 2.00, 1, 'Các kịch bản trung bình của IPCC (RCP4.5) ước tính mức tăng trung bình khoảng 0,6 m – 0,9 m so với mức hiện tại nếu không có biện pháp giảm phát thải mạnh.\n---', NULL, '2026-11-18 14:38:06', '2026-11-18 14:38:06'),
(122, 16, 64, 'Trong hệ thống sông lớn của Việt Nam, sông nào có lưu vực rộng nhất?', NULL, 'single_choice', 2.00, 2, 'Lưu vực sông Cửu Long (Mekong) bao phủ hơn 800 000 km², chiếm khoảng 70 % diện tích đồng bằng sông Cửu Long, lớn hơn hẳn lưu vực sông Hồng (≈ 67 000 km²) và các lưu vực khác.\n---', NULL, '2026-11-18 14:38:06', '2026-11-18 14:38:06'),
(123, 16, 64, 'Địa hình nào chiếm diện tích lớn nhất trên lãnh thổ Việt Nam?', NULL, 'single_choice', 2.00, 3, 'Khoảng 80 % diện tích đất liền Việt Nam là núi non, trong đó đa số là các dãy núi và đồi thuộc hệ thống dãy Trường Sơn, dãy Hoành Sơn, dãy Bạch Mã… Đồng bằng chiếm khoảng 15 % và cao nguyên chỉ khoảng 5 %.\n---', NULL, '2026-11-18 14:38:06', '2026-11-18 14:38:06'),
(124, 16, 64, 'Khu vực nào sau đây là “điểm nóng” của bão nhiệt đới ở khu vực Tây Thái Bình Dương?', NULL, 'single_choice', 2.00, 4, 'Phía tây Thái Bình Dương (đặc biệt là quần đảo Philippines) là khu vực có tần suất bão nhiệt đới cao nhất do vị trí nằm trong “vòng bão” (tropical cyclone belt) và có nguồn nhiệt, độ ẩm dồi dào.\n---', NULL, '2026-11-18 14:38:06', '2026-11-18 14:38:06'),
(125, 16, 64, 'Trong bản đồ địa hình, ký hiệu “▲” thường dùng để biểu thị:', NULL, 'single_choice', 2.00, 5, 'Ký hiệu “▲” (tam giác) trong bản đồ địa hình đại diện cho đỉnh núi hoặc đồi, thường đi kèm với độ cao (mét) được ghi bên cạnh. Các ký hiệu khác: “●” cho đảo, “■” cho hồ, “▭” cho đồng cỏ.\n---\n*Ghi chú:* Các câu hỏi đã được viết theo chuẩn EduTest, dễ sao chép trực tiếp vào ngân hàng câu hỏi của hệ thống EduTest.', NULL, '2026-11-18 14:38:06', '2026-11-18 14:38:06'),
(126, 16, 64, 'Ký hiệu địa lý “°N” và “°E” dùng để chỉ:', NULL, 'single_choice', 2.00, 6, '“°N” (bắc) và “°E” (đông) là đơn vị đo vĩ độ và kinh độ trong hệ tọa độ địa lý.\n---', NULL, '2026-11-18 14:38:06', '2026-11-18 14:38:06'),
(127, 16, 64, 'Địa hình nào chiếm diện tích lớn nhất trên lãnh thổ Việt Nam?', NULL, 'single_choice', 2.00, 7, 'Khoảng 80 % diện tích đất liền Việt Nam là núi non, trong khi đồng bằng chỉ chiếm khoảng 15 %.\n---', NULL, '2026-11-18 14:38:06', '2026-11-18 14:38:06'),
(128, 16, 64, 'Sông nào được gọi là “sông xanh” vì màu nước trong xanh, chảy qua miền Tây Nam Bộ?', NULL, 'single_choice', 2.00, 8, 'Sông Cửu Long (Mekong) có màu nước trong xanh, đặc biệt ở các khu vực đồng bằng sông Cửu Long, nên được dân địa phương gọi là “sông xanh”.\n---', NULL, '2026-11-18 14:38:06', '2026-11-18 14:38:06'),
(129, 16, 64, 'Địa danh “Hạ Long” thuộc tỉnh nào?', NULL, 'single_choice', 2.00, 9, 'Vịnh Hạ Long nằm trong tỉnh Quảng Ninh, là di sản thiên nhiên thế giới.\n---', NULL, '2026-11-18 14:38:06', '2026-11-18 14:38:06'),
(130, 16, 64, 'Ký hiệu “°C” trong bản đồ địa lý thường dùng để chỉ:', NULL, 'single_choice', 2.00, 10, 'Trên bản đồ địa hình, các đường đồng mức (contour) thường được ghi kèm độ cao tính bằng mét (m) hoặc độ (°), ví dụ 500 m hoặc 500 ° (độ cao).\n---', NULL, '2026-11-18 14:38:06', '2026-11-18 14:38:06'),
(131, 16, 64, 'Trong chu kỳ nước, quá trình “thẩm thấu” (evaporation) xảy ra ở:', NULL, 'single_choice', 2.00, 11, 'Thẩm thấu là quá trình bốc hơi nước từ bề mặt các nguồn nước (đại dương, sông, hồ) lên không khí.\n---', NULL, '2026-11-18 14:38:06', '2026-11-18 14:38:06'),
(132, 16, 64, 'Khu vực nào được xem là “điểm nóng” bão nhiệt đới ở Tây Thái Bình Dương?', NULL, 'single_choice', 2.00, 12, 'Vùng Tây Thái Bình Dương, đặc biệt là quần đảo Philippines, có tần suất bão nhiệt đới cao nhất do vị trí nằm trong “vòng bão” (tropical cyclone belt).\n---', NULL, '2026-11-18 14:38:06', '2026-11-18 14:38:06'),
