(379, 36, 'A', 'Không được khiếu nại vì quyết định đã được ban hành.', 0, '2026-11-11 16:37:20', '2026-11-11 16:37:20'),
(380, 36, 'B', 'Có quyền khởi kiện ra tòa án để yêu cầu hủy bỏ quyết định.', 1, '2026-11-11 16:37:20', '2026-11-11 16:37:20'),
(381, 36, 'C', 'Chỉ được yêu cầu cơ quan cấp trên xem xét lại, không được khởi kiện.', 0, '2026-11-11 16:37:20', '2026-11-11 16:37:20'),
(382, 36, 'D', 'Phải chấp nhận quyết định và không có quyền khiếu nại.', 0, '2026-11-11 16:37:20', '2026-11-11 16:37:20'),
(383, 35, 'A', 'Khi không có quy định nào trong luật, pháp lệnh, nghị định, quyết định.', 1, '2026-11-11 16:37:35', '2026-11-11 16:37:35'),
(384, 35, 'B', 'Khi có quy định trong luật nhưng người dân muốn áp dụng luật lệ truyền thống.', 0, '2026-11-11 16:37:35', '2026-11-11 16:37:35'),
