(391, 33, 'A', 'Trách nhiệm hình sự đối với hành vi vi phạm luật hình sự.', 0, '2026-11-11 16:38:09', '2026-11-11 16:38:09'),
(392, 33, 'B', 'Trách nhiệm bồi thường thiệt hại do hành vi vi phạm pháp luật dân sự gây ra cho người khác.', 1, '2026-11-11 16:38:09', '2026-11-11 16:38:09'),
(393, 33, 'C', 'Trách nhiệm hành chính đối với vi phạm quy định hành chính.', 0, '2026-11-11 16:38:09', '2026-11-11 16:38:09'),
