(395, 32, 'A', 'Không cần làm gì, vì việc điều tra là trách nhiệm của cơ quan chức năng.', 0, '2026-11-11 16:38:25', '2026-11-11 16:38:25'),
(396, 32, 'B', 'Báo cáo cho cơ quan công an, cơ quan quản lý nhà nước có thẩm quyền hoặc các tổ chức, cá nhân có thẩm quyền.', 1, '2026-11-11 16:38:25', '2026-11-11 16:38:25'),
(397, 32, 'C', 'Tự mình tiến hành xử lý hành vi vi phạm mà không thông báo cho cơ quan chức năng.', 0, '2026-11-11 16:38:25', '2026-11-11 16:38:25'),
